  @override
  String get learningJourneyShortSurahsWhyThisMatters =>
      'Kurze Suren sind der einfachste Ort, um Auswendiglernen, Rezitation und Bedeutung zu verbinden.';

  @override
  String get learningJourneyStageQuranOpenTitle =>
      'Wie man sich dem Koran nähert';

  @override
  String get learningJourneyStageQuranOpenSummary =>
      'Beginnen Sie mit einem einfachen Rahmen für die Lektüre des Korans als Führung, Anbetung und tägliche Rückkehr.';

  @override
  String get learningJourneyStageQuranReadTitle =>
      'Beginnen Sie klar und deutlich mit dem Lesen';

