  @override
  String get learningJourneyStageFatihahReadTitle =>
      'Verse 1-2: Lob und Herrschaft';

  @override
  String get learningJourneyStageFatihahReadSummary =>
      'Begin with the opening praise of Allah and what it means to call Him the Lord of all worlds.';

  @override
  String get learningJourneyStageFatihahRecitationTitle =>
      'Verse 3-5: Barmherzigkeit, Gericht und Anbetung';

  @override
  String get learningJourneyStageFatihahRecitationSummary =>
      'Sehen Sie, wie Barmherzigkeit, Verantwortung und exklusiver Gottesdienst im Mittelpunkt von Al-Fatihah stehen.';

  @override
  String get learningJourneyStageFatihahReflectionTitle =>
      'Verse 6-7: Führung und der gerade Weg';

  @override
  String get learningJourneyStageFatihahReflectionSummary =>
      'Reflect on what it means to ask Allah for guidance every day inside salah.';

  @override
  String get learningJourneyStageFatihahCompletionTitle =>
      'Tragen Sie Al-Fatihah ins Gebet';

  @override
  String get learningJourneyStageFatihahCompletionSummary =>
      'Sammeln Sie die Themen von Al-Fatihah und entscheiden Sie, wie Sie sich an sie erinnern, wenn Sie im Gebet stehen.';

  @override
  String get learningJourneyStageShortSurahIkhlasTitle => 'Klar, Al-Ikhlas';

  @override
  String get learningJourneyStageShortSurahIkhlasSummary =>
      'Erfahren Sie die kurze Sure des reinen Tauhid und warum sie eine so zentrale Bedeutung hat.';

  @override
  String get learningJourneyStageShortSurahFalaqTitle => 'Klar, Al-Falaq';

  @override
  String get learningJourneyStageShortSurahFalaqSummary =>
      'Vertiefe diese Sure des Schutzsuchens und beachte, wie sie Schutz durch Allah lehrt.';

  @override
  String get learningJourneyStageShortSurahNasTitle => 'Klar, An-Nas';

  @override
  String get learningJourneyStageShortSurahNasSummary =>
      'Erfahren Sie, wie diese kurze Sure Zuflucht, Abhängigkeit und Schutz des Herzens lehrt.';

  @override
  String get learningJourneyStageShortSurahKafirunTitle => 'Klar, Al-Kafirun';

  @override
  String get learningJourneyStageShortSurahKafirunSummary =>
      'Sehen Sie, wie diese kurze Sure Klarheit, Treue zur Anbetung und respektvolle Festigkeit lehrt.';

  @override
  String get learningJourneyStageShortSurahKawtharTitle => 'Klar, Al-Kawthar';

  @override
  String get learningJourneyStageShortSurahKawtharSummary =>
      'Studieren Sie diese kurze Sure über Fülle, Dankbarkeit und Anbetung durch Opfer.';

  @override
  String get learningJourneyStageShortSurahCompletionTitle =>
      'Tragen Sie kurze Suren ins Gebet ein';

  @override
  String get learningJourneyStageShortSurahCompletionSummary =>
      'Wählen Sie abschließend aus, wie diese kurzen Suren die Rezitation, das Gedächtnis und die Reflexion in der Salah vertiefen können.';

  @override
  String get learningJourneyStageAlphabetCompletionTitle =>
      'Bereit zum Lesen der Grundlagen';

  @override
  String get learningJourneyStageAlphabetCompletionSummary =>
      'Beenden Sie die Alphabet-Reise, indem Sie überprüfen, was stabil ist, und mit Zuversicht in die Lesemarken übergehen.';

  @override
  String get learningJourneyStageReadingCompletionTitle =>
      'Gehen Sie zum Rezitationsverständnis über';

  @override
  String get learningJourneyStageReadingCompletionSummary =>
      'Zum Abschluss verknüpfen Sie Ihr neues Selbstvertrauen beim Lesen mit der Bedeutung des Korans und vertrauten Rezitationen.';

  @override
  String get learningJourneyStageReciteCompletionTitle =>
      'Bringen Sie Bedeutung in den Gottesdienst';

  @override
  String get learningJourneyStageReciteCompletionSummary =>
      'Schließen Sie ab, indem Sie bekannte Sätze mit Gebet, Dhikr und Ihrem nächsten Arabisch- oder Koranschritt verbinden.';

  @override
  String get learningJourneyQuranToolSearchSubtitle =>
      'Verwenden Sie die Suche, wenn Sie Hilfe bei der Suche nach einer Passage oder einem Thema benötigen.';

  @override
  String get learningJourneyQuranBookmarksSupportSubtitle =>
