  @override
  String get learningJourneyQuranReadTakeaway1 =>
      'Kleines, stetiges Lesen ist ein echter Fortschritt.';

  @override
  String get learningJourneyQuranReadTakeaway2 =>
      'Al-Fatihah ist ein starker erster Zugang.';

  @override
  String get learningJourneyQuranReadTakeaway3 =>
      'Kontinuität ist wichtiger als Intensität.';

  @override
  String get learningJourneyQuranReadReflection =>
      'Welcher Moment Ihres Tages könnte realistischerweise Ihr Koran-Anker werden?';

  @override
